import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();
const { fontFamily: inter } = loadInter();



export type ExamPrepTemplateProps = Record<string, any>;

const ExamPrepTemplate: React.FC<ExamPrepTemplateProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 8,
  daysRemaining = "30 DAYS",
  examContext = "BEFORE THE MATHS EXAM",
  hookStatement = "Here's exactly the plan I give my own students hour by hour.",
  primaryColor = "#00E5FF",
  textColor = "#FFFFFF",
  glassOpacity = 0.4,
  enableGlow = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors for background color
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations
  const safeTop = height * 0.15;
  const contentWidth = width * 0.85;

  // Timing constants
  const startCard = 5;
  const startDays = 15;
  const startContext = 25;
  const startHook = 40;
  const startAccent = 35;

  // Animations
  const cardOpacity = interpolate(frame, [startCard, startCard + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const cardY = spring({
    frame: frame - startCard,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const daysScale = spring({
    frame: frame - startDays,
    fps,
    config: { damping: 12, stiffness: 150 },
  });
  const daysOpacity = interpolate(frame, [startDays, startDays + 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const contextY = interpolate(frame, [startContext, startContext + 15], [20, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const contextOpacity = interpolate(frame, [startContext, startContext + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const hookY = interpolate(frame, [startHook, startHook + 15], [20, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const hookOpacity = interpolate(frame, [startHook, startHook + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const accentHeight = spring({
    frame: frame - startAccent,
    fps,
    config: { damping: 20, stiffness: 100 },
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Main Content Container - Positioned in the upper/middle safe zone */}
      <div
        style={{
          position: "absolute",
          top: safeTop,
          left: (width - contentWidth) / 2,
          width: contentWidth,
          display: "flex",
          flexDirection: "column",
          opacity: cardOpacity,
          transform: `translateY(${(1 - cardY) * 50}px)`,
          transition: "none",
        }}
      >
        {/* Glassmorphic Card */}
        <div
          style={{
            backgroundColor: `rgba(0, 0, 0, ${glassOpacity})`,
            backdropFilter: "blur(16px)",
            WebkitBackdropFilter: "blur(16px)",
            borderRadius: "32px",
            padding: "60px 50px",
            border: "1px solid rgba(255, 255, 255, 0.1)",
            boxShadow: enableGlow ? `0 20px 60px rgba(0,0,0,0.5), 0 0 40px ${primaryColor}20` : "none",
            display: "flex",
            flexDirection: "column",
            gap: "24px",
            position: "relative",
            overflow: "hidden",
            transition: "none",
          }}
        >
          {/* Animated Accent Line */}
          <div
            style={{
              position: "absolute",
              left: 0,
              top: "10%",
              width: "8px",
              height: "80%",
              backgroundColor: "rgba(255,255,255,0.05)",
              borderRadius: "0 8px 8px 0",
              transition: "none",
            }}
          >
             <div
              style={{
                width: "100%",
                height: `${accentHeight * 100}%`,
                backgroundColor: primaryColor,
                boxShadow: enableGlow ? `0 0 15px ${primaryColor}` : "none",
                borderRadius: "0 8px 8px 0",
                transition: "none",
              }}
            />
          </div>

          {/* Days Remaining (The Big Hook) */}
          <div
            style={{
              transform: `scale(${daysScale})`,
              opacity: daysOpacity,
              transformOrigin: "left center",
              transition: "none",
            }}
          >
            <h1
              style={{
                fontFamily: spaceGrotesk,
                fontSize: "120px",
                fontWeight: 800,
                color: primaryColor,
                margin: 0,
                lineHeight: 1,
                letterSpacing: "-0.04em",
                textShadow: enableGlow ? `0 0 30px ${primaryColor}60` : "none",
              }}
            >
              {daysRemaining}
            </h1>
          </div>

          {/* Context / Subheading */}
          <div
            style={{
              transform: `translateY(${contextY}px)`,
              opacity: contextOpacity,
              transition: "none",
            }}
          >
            <h2
              style={{
                fontFamily: inter,
                fontSize: "42px",
                fontWeight: 600,
                color: textColor,
                margin: 0,
                letterSpacing: "0.1em",
                textTransform: "uppercase",
                opacity: 0.9,
              }}
            >
              {examContext}
            </h2>
          </div>

          <div 
             style={{ 
               height: "2px", 
               width: "100%", 
               backgroundColor: "rgba(255,255,255,0.1)",
               marginTop: "16px",
               marginBottom: "16px",
               opacity: contextOpacity,
               transition: "none",
             }} 
          />

          {/* Value Proposition / Body Text */}
          <div
            style={{
              transform: `translateY(${hookY}px)`,
              opacity: hookOpacity,
              transition: "none",
            }}
          >
            <p
              style={{
                fontFamily: inter,
                fontSize: "52px",
                fontWeight: 400,
                color: textColor,
                margin: 0,
                lineHeight: 1.4,
                letterSpacing: "-0.01em",
                opacity: 0.85,
              }}
            >
              {hookStatement}
            </p>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ExamPrepTemplate;